import React, { useEffect } from "react";
import ajax from "@/utils/ajax";
import store from "./store";
import { Button, List, Menu, Message, Modal, Typography } from "@arco-design/web-react";
import styles from './style.module.less';
import { SchemaTable } from "@/components/schema";
import { scrollToElementById } from "@/utils";
import { useObserver } from "mobx-react-lite";


const Index = () => {

    useEffect(() => {
        store.init();
    },[])

    
    return useObserver(() => {

        console.log('store.dataList', store.dataList)

        return (
            <div className="page-container">
                <div className={styles.component}>
                    <List
                        className={styles.list}
                        style={{ width: 220 }}
                        header={(
                            <div className={styles.header}>
                                数据字典
                                <Button type="primary" size="small"
                                    onClick={() => {
                                        Modal.confirm({
                                            title: "提示",
                                            content: "数据初始化",
                                            onOk: () => {
                                                ajax.post(`/data-manage/init`, {}).then((res) => {
                                                    Message.success("数据初始化")
                                                })
                                            }
                                        })
                                    }}
                                >
                                    初始化
                                </Button>
                            </div>
                        )}
                        dataSource={store.dataList}
                        render={(item, index) => (
                            <List.Item
                                key={index}
                                className={styles.item}
                                onClick={() => {
                                    scrollToElementById(item.id);
                                }}
                            >
                                {item.tableName}
                                {/* <a href={`#${item}`}>{item}</a> */}
                            </List.Item>
                        )}
                    />
                    <div className={styles['content']}>
                        {store.dataList.map((o, i) => {
                            return (
                                <div key={o.id} id={o.id}>
                                    <SchemaTable
                                        data={o.column}
                                        pagination={false}
                                        schema={{
                                            "type": "object",
                                            "properties": {
                                                "key": {
                                                    "type": "string",
                                                    "default": "id",
                                                    "title": "字段名称"
                                                },
                                                "type": {
                                                    "type": "string",
                                                    "default": "integer",
                                                    "title": "字段类型"
                                                },
                                                "length": {
                                                    "type": "integer",
                                                    "default": 11,
                                                    "title": "字段长度"
                                                },
                                                "desc": {
                                                    "type": "string",
                                                    "default": "用户I23D2323",
                                                    "title": "备注"
                                                },
                                            }
                                        }}
                                    />
                                </div>
                            )
                        })}
                    </div>
                </div>
            </div>
        )
    })
}

export default Index;